// protobuf JSON <-> binary codec, same contract as grpc-wasm/Exports.cs.
// proto.js is generated by `bun run gen` (pbjs static-module, no reflection/eval).
import $root from './proto.js';

const CHUNK = 0x8000;

export const b64ToBytes = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const bytesToB64 = (bytes) => {
  let s = '';
  for (let i = 0; i < bytes.length; i += CHUNK) s += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  return btoa(s);
};

// static root is a plain namespace object: walk it by dotted name
const type = (name) => {
  const t = name.split('.').reduce((o, k) => o?.[k], $root);
  if (!t?.encode) throw new Error(`unknown type: ${name}`);
  return t;
};

// pbjs fromObject only reads camelCase field names; Google's JsonParser also takes
// proto (snake_case) names, so resolve either via a read-only view. Map keys are
// looked up on the map object itself, so they stay untouched.
const snake = (s) => s.replace(/[A-Z]/g, (c) => '_' + c.toLowerCase());
const tolerant = (o) => {
  if (Array.isArray(o)) return o.map(tolerant);
  if (!o || typeof o !== 'object') return o;
  return new Proxy(o, {
    get: (t, k) => {
      if (typeof k !== 'string') return t[k];
      return tolerant(k in t ? t[k] : t[snake(k)]);
    },
  });
};

// camelCase, int64 as string, enums by name, bytes as base64, defaults omitted:
// matches Google.Protobuf JsonFormatter defaults
const toJson = (t, msg) => t.toObject(msg, { longs: String, enums: String, bytes: String });

export function Encode(name, json) {
  const t = type(name);
  const obj = typeof json === 'string' ? JSON.parse(json) : json;
  return bytesToB64(t.encode(t.fromObject(tolerant(obj))).finish());
}

export function Decode(name, b64) {
  const t = type(name);
  return JSON.stringify(toJson(t, t.decode(b64ToBytes(b64))));
}

export function Types() {
  const out = new Set();
  const seen = new Set();
  (function walk(ns, prefix) {
    if (!ns || typeof ns !== 'object' || seen.has(ns)) return;
    seen.add(ns);
    for (const [k, v] of Object.entries(ns)) {
      if (typeof v === 'function' && v.encode) out.add(`${prefix}${k}`);
      else if (typeof v === 'object') walk(v, `${prefix}${k}.`);
    }
  })($root, '');
  return [...out].sort();
}
